<?php require 'config/config.php';if(user())go(BASE_URL.'/dashboard.php');$err='';if($_POST){check();$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([trim($_POST['email'])]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password'])){unset($u['password']);$_SESSION['user']=$u;go(BASE_URL.'/dashboard.php');}$err='Invalid email or password.';}$title='Login';require 'config/header.php';?><div class="auth"><div class="panel"><h1>Welcome back</h1><?php if($err):?><div class="err"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" required></label><button class="btn">Login</button></form></div></div><?php require 'config/footer.php';?>
